import { createRoot } from 'react-dom/client';
import { MossApp } from './components/moss-app';
createRoot(document.getElementById('root')!).render(<MossApp />);

// Offline/install support (dist/sw.js is generated by the build). Only on a secure
// origin; a failure just means the game stays online-only.
if ('serviceWorker' in navigator && window.isSecureContext) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js').catch(() => {});
  });
}
